const inp = $input.first().json;
const code = inp.query || inp.input || inp.code || inp.programCode || '';

const VALID_COMMANDS = ['GET','GETNOT','DUP','NOT','AND','OR','XOR','MOV','CMOV','SET','CSET','CINC','CDEC','CMP','GT','LE'];

const STACK_EFFECTS = {
  'GET':   { pop: 0, push: 1 }, 'GETNOT': { pop: 0, push: 1 },
  'NOT': { pop: 1, push: 1 },
  'AND':   { pop: 2, push: 1 }, 'OR': { pop: 2, push: 1 }, 'XOR': { pop: 2, push: 1 },
  'MOV':   { pop: 1, push: 0 }, 'CMOV': { pop: 1, push: 0 },
  'SET':   { pop: 0, push: 0 }, 'CSET': { pop: 1, push: 0 },
  'CINC':  { pop: 1, push: 0 }, 'CDEC': { pop: 1, push: 0 },
  'CMP':   { pop: 0, push: 1 }, 'GT': { pop: 0, push: 1 }, 'LE': { pop: 0, push: 1 }
};

const LIMITS = { 'I': 64, 'O': 64, 'M': 1024, 'T': 128, 'C': 128 };

const ALLOWED_SUBJECTS = {
  'GET':   ['I','O','M','T'],
  'GETNOT':['I','O','M','T'],
  'MOV':   ['O','M'],
  'CMOV':  ['O','M'],
  'SET':   ['T','C'],
  'CSET':  ['T','C'],
  'CINC':  ['C'],
  'CDEC':  ['C'],
  'CMP':   ['C'],
  'GT':    ['C'],
  'LE':    ['C'],
};

const rawLines = code.split('\n');
const errors = [];
const trace = [];
let depth = 0;
let lineNum = 0;

for (const rawLine of rawLines) {
  lineNum++;
  // Skip totally blank lines silently
  if (rawLine.trim() === '') continue;

  // --- FORMAT-CHECKS auf der Roh-Zeile (vor trim) ---
  if (/^[ \t]/.test(rawLine)) {
    errors.push(`Zeile ${lineNum}: fuehrendes Whitespace nicht erlaubt — Befehle muessen am Zeilenanfang beginnen.`);
  }
  if (rawLine.includes('//')) {
    errors.push(`Zeile ${lineNum}: '//' ist KEIN FPC-Kommentar — nur '#' am Zeilenanfang ist erlaubt. Inline-Kommentare sind verboten.`);
  }
  if (rawLine.includes('(') || rawLine.includes(')')) {
    errors.push(`Zeile ${lineNum}: Klammern '(' ')' sind im FPC-Code verboten — der Parser kennt keine Gruppierung.`);
  }
  if (/;/.test(rawLine)) {
    errors.push(`Zeile ${lineNum}: Semikolon ';' ist nicht erlaubt.`);
  }

  const line = rawLine.trim();
  if (line.startsWith('#')) {
    trace.push({ l: lineNum, i: line, d: depth, comment: true });
    continue;
  }

  const parts = line.split(/\s+/);
  const cmd = parts[0].toUpperCase();

  if (!VALID_COMMANDS.includes(cmd)) {
    errors.push(`Zeile ${lineNum}: Unbekannter Befehl '${cmd}'`);
    continue;
  }

  if (cmd === 'DUP') {
    const k = parts.length >= 2 ? parseInt(parts[1]) : 2;
    if (isNaN(k) || k < 0) {
      errors.push(`Zeile ${lineNum}: DUP-Argument '${parts[1]}' ungueltig`);
      continue;
    }
    if (k === 1) errors.push(`Zeile ${lineNum}: FEHLER: 'DUP 1' ist ein NOP — Stack unveraendert!`);
    if (k > 1 && depth < 1) errors.push(`Zeile ${lineNum}: Stack-Unterlauf bei 'DUP' (braucht 1, hat ${depth})`);
    const beforeDup = depth;
    const pushCount = Math.max(0, k - 1);
    depth += pushCount;
    trace.push({ l: lineNum, i: line, before: beforeDup, after: depth });
    continue;
  }

  const fx = STACK_EFFECTS[cmd];
  const before = depth;
  const minReq = fx.needsMin || fx.pop;

  if (depth < minReq)
    errors.push(`Zeile ${lineNum}: Stack-Unterlauf bei '${cmd}' (braucht ${minReq}, hat ${depth})`);

  if (ALLOWED_SUBJECTS[cmd] && parts.length >= 2) {
    const subj = parts[1].toUpperCase();
    const allowed = ALLOWED_SUBJECTS[cmd];
    const isConstant = (cmd === 'GET') && (parts[1] === '0' || parts[1] === '1');
    if (!isConstant) {
      if (!allowed.includes(subj)) {
        errors.push(`Zeile ${lineNum}: '${cmd} ${subj}' ist ungueltig — ${cmd} erlaubt nur: ${allowed.join('/')}`);
      } else if (parts.length >= 3) {
        const addr = parseInt(parts[2]);
        if (LIMITS[subj] !== undefined && (isNaN(addr) || addr < 0 || addr >= LIMITS[subj]))
          errors.push(`Zeile ${lineNum}: Adresse ${parts[2]} ungueltig fuer ${subj} (erlaubt: 0-${LIMITS[subj]-1})`);
      }
    }
    // Range-Check fuer GT/LE/CMP-Werte
    if ((cmd === 'GT' || cmd === 'LE' || cmd === 'CMP') && parts.length >= 4) {
      const v = parseInt(parts[3]);
      if (!isNaN(v) && v < 0) {
        errors.push(`Zeile ${lineNum}: ${cmd} mit negativem Wert (${v}) — Counter sind unsigned, nutze stattdessen einen direkten LE-Check oder ein anderes Pattern.`);
      }
    }
  }

  // Verbotene Range-Check-Kombination: 'GT C n k' direkt gefolgt von 'LE C n k' + 'AND' = leere Menge
  // (dieser Check ist schwer ohne Kontext, daher Hinweis im Prompt)

  depth = Math.max(0, depth - fx.pop + fx.push);
  trace.push({ l: lineNum, i: line, before, after: depth });
}

if (depth !== 0) errors.push(`Stack nicht leer am Ende: Tiefe=${depth}`);

const valid = errors.length === 0;
let result = `Validierung: ${valid ? 'GUELTIG' : 'FEHLERHAFT — DEPLOY VERBOTEN, ERST CODE KORRIGIEREN!'}\n`;
if (!valid) { result += 'Fehler:\n' + errors.map(e => `- ${e}`).join('\n') + '\n'; }
result += 'Stack-Trace:\n' + trace.filter(t => !t.comment).map(t => `  ${t.l}: [${t.before}] ${t.i} [${t.after}]`).join('\n');
return result;

try {
  const response = await $http.request({
    method: 'GET',
    url: 'http://localhost:5555/api/program',
    returnFullResponse: true
  });

  let body = response.body;
  if (typeof body === 'string') {
    try { body = JSON.parse(body); } catch { return body; }
  }
  if (!body || typeof body !== 'object') {
    return `Steuerung erreichbar, aber Antwort nicht interpretierbar: ${JSON.stringify(body)}`;
  }

  const lines = Number(body.sourceLines) || 0;
  const code = body.programCode || body.source || '';
  const hasParseError = body.hasParseError === true;
  const isExecutable = body.isExecutable === true || (lines > 0 && !hasParseError && code);

  if (!code || lines === 0) {
    return 'KEIN PROGRAMM GELADEN: Die Steuerung ist erreichbar, aber es ist aktuell kein Programm geladen.';
  }

  if (hasParseError) {
    const msg = body.parseErrorMessage ? ` (${body.parseErrorMessage})` : '';
    return `PROGRAMM HAT PARSE-FEHLER${msg}:\n\n${code}`;
  }

  if (!isExecutable) {
    return `PROGRAMM NICHT AUSFUEHRBAR (${lines} Zeilen). Code:\n\n${code}`;
  }

  return `Programm von Steuerung geladen (${lines} Zeilen, ausfuehrbar):\n\n${code}`;

} catch (e) {
  return `FEHLER: Steuerung nicht erreichbar. Details: ${e.message}`;
}

// FPC Dry-Run Simulator — JS port of ExecutionUnit.Execute
const inp = $input.first().json;
let req;
if (typeof inp.query === 'string') {
  try { req = JSON.parse(inp.query); } catch (e) { req = { error: 'invalid query JSON: ' + e.message }; }
} else if (typeof inp.input === 'string') {
  try { req = JSON.parse(inp.input); } catch (e) { req = { error: 'invalid input JSON: ' + e.message }; }
} else {
  req = inp;
}
if (req.error) return JSON.stringify({ error: req.error });

const code = req.code || req.programCode || '';
if (!code) return JSON.stringify({ error: 'code required (key: code or programCode)' });

const inputs = Array.isArray(req.inputs) ? req.inputs.map(v => v ? 1 : 0) : new Array(20).fill(0);
const counters = {};
for (const k of Object.keys(req.counters || {})) counters[k] = parseInt(req.counters[k]) || 0;
const memory = {};
for (const k of Object.keys(req.memory || {})) memory[k] = req.memory[k] ? 1 : 0;
const timers = {};
for (const k of Object.keys(req.timers || {})) timers[k] = req.timers[k] ? 1 : 0;
const outputs = new Array(20).fill(0);
const cycles = Math.max(1, Math.min(100, parseInt(req.cycles) || 1));

const lines = [];
const rawLines = code.split(/\r?\n/);
for (let i = 0; i < rawLines.length; i++) {
  const t = rawLines[i].trim();
  if (!t || t.startsWith('#') || t.startsWith('//')) continue;
  lines.push({ raw: t, lineNum: i + 1, parts: t.split(/\s+/) });
}

const stack = [];
const errors = [];

function pop() {
  if (stack.length < 1) throw new Error('Stack-Unterlauf');
  return stack.pop();
}

function step(ln) {
  const p = ln.parts;
  const cmd = p[0].toUpperCase();
  let a, b;
  switch (cmd) {
    case 'GET':
      if (p[1] === '0') { stack.push(0); break; }
      if (p[1] === '1') { stack.push(1); break; }
      {
        const sub = p[1].toUpperCase();
        const addr = parseInt(p[2]);
        if (sub === 'I') stack.push(inputs[addr] ? 1 : 0);
        else if (sub === 'O') stack.push(outputs[addr] ? 1 : 0);
        else if (sub === 'M') stack.push(memory[addr] ? 1 : 0);
        else if (sub === 'T') stack.push(timers[addr] ? 1 : 0);
        else throw new Error('GET ' + sub + ' ungueltig');
      }
      break;
    case 'GETNOT': {
      const sub = p[1].toUpperCase();
      const addr = parseInt(p[2]);
      if (sub === 'I') stack.push(inputs[addr] ? 0 : 1);
      else if (sub === 'O') stack.push(outputs[addr] ? 0 : 1);
      else if (sub === 'M') stack.push(memory[addr] ? 0 : 1);
      else if (sub === 'T') stack.push(timers[addr] ? 0 : 1);
      else throw new Error('GETNOT ' + sub + ' ungueltig');
      break;
    }
    case 'DUP': {
      const k = p.length >= 2 ? (parseInt(p[1]) || 2) : 2;
      if (stack.length < 1) throw new Error('DUP: Stack-Unterlauf');
      const top = stack[stack.length - 1];
      for (let i = 1; i < k; i++) stack.push(top);
      break;
    }
    case 'NOT':
      a = pop();
      stack.push(a ? 0 : 1);
      break;
    case 'AND':
      a = pop(); b = pop();
      stack.push((a && b) ? 1 : 0);
      break;
    case 'OR':
      a = pop(); b = pop();
      stack.push((a || b) ? 1 : 0);
      break;
    case 'XOR':
      a = pop(); b = pop();
      stack.push((a ^ b) ? 1 : 0);
      break;
    case 'MOV': {
      const sub = p[1].toUpperCase();
      const addr = parseInt(p[2]);
      const v = pop();
      if (sub === 'O') outputs[addr] = v ? 1 : 0;
      else if (sub === 'M') memory[addr] = v ? 1 : 0;
      else throw new Error('MOV ' + sub + ' ungueltig');
      break;
    }
    case 'CMOV': {
      const sub = p[1].toUpperCase();
      const addr = parseInt(p[2]);
      const val = parseInt(p[3]);
      const cond = pop();
      if (cond) {
        if (sub === 'O') outputs[addr] = val > 0 ? 1 : 0;
        else if (sub === 'M') memory[addr] = val > 0 ? 1 : 0;
      }
      break;
    }
    case 'SET': {
      const sub = p[1].toUpperCase();
      const addr = parseInt(p[2]);
      const val = parseInt(p[3]);
      if (sub === 'T') timers[addr] = val ? 1 : 0;
      else if (sub === 'C') counters[addr] = val;
      break;
    }
    case 'CSET': {
      const sub = p[1].toUpperCase();
      const addr = parseInt(p[2]);
      const val = parseInt(p[3]);
      const cond = pop();
      if (cond) {
        if (sub === 'T') timers[addr] = val ? 1 : 0;
        else if (sub === 'C') counters[addr] = val;
      }
      break;
    }
    case 'CINC': {
      const addr = parseInt(p[2]);
      const inc = p.length >= 4 ? (parseInt(p[3]) || 1) : 1;
      const cond = pop();
      if (cond) counters[addr] = (counters[addr] || 0) + inc;
      break;
    }
    case 'CDEC': {
      const addr = parseInt(p[2]);
      const dec = p.length >= 4 ? (parseInt(p[3]) || 1) : 1;
      const cond = pop();
      if (cond) counters[addr] = (counters[addr] || 0) - dec;
      break;
    }
    case 'CMP':
      stack.push((counters[parseInt(p[2])] || 0) === parseInt(p[3]) ? 1 : 0);
      break;
    case 'GT':
      stack.push((counters[parseInt(p[2])] || 0) > parseInt(p[3]) ? 1 : 0);
      break;
    case 'LE':
      stack.push((counters[parseInt(p[2])] || 0) <= parseInt(p[3]) ? 1 : 0);
      break;
    default:
      throw new Error('Unbekannte Instruktion: ' + cmd);
  }
}

const cycleResults = [];
let crashed = false;
for (let c = 0; c < cycles && !crashed; c++) {
  stack.length = 0;
  for (const ln of lines) {
    try { step(ln); }
    catch (e) {
      errors.push({ cycle: c, line: ln.lineNum, instr: ln.raw, error: e.message, stackDepth: stack.length });
      crashed = true;
      break;
    }
  }
  cycleResults.push({
    cycle: c,
    outputs: outputs.slice(0, 8),
    counters: { ...counters },
    memory: { ...memory },
    timers: { ...timers },
    finalStackDepth: stack.length,
    stackLeftover: stack.slice()
  });
}

const last = cycleResults[cycleResults.length - 1] || {};
return JSON.stringify({
  outputs: last.outputs || outputs.slice(0, 8),
  counters: last.counters || counters,
  memory: last.memory || memory,
  timers: last.timers || timers,
  finalStackDepth: last.finalStackDepth != null ? last.finalStackDepth : stack.length,
  stackLeftover: last.stackLeftover || stack.slice(),
  errors,
  cycles: cycleResults
}, null, 2);
